# ---- views/react.html ------------------------------------------------------
ARQUIVOS['views/react.html'] = r'''{{
# -----------------------------------------------------------------------------
#  Trecho incluído pelas páginas que usam React (variável "componente").
#  React 18 e ReactDOM (UMD) são cópias locais em static/js/vendor/.
#  Os componentes ficam em static/js/componentes/<nome>.jsx (fonte legível) e
#  já vão PRÉ-COMPILADOS em static/js/componentes/compilado/<nome>.js, então a
#  página não precisa de Babel nem de internet.  Se alguém editar o .jsx (o
#  hash gravado no cabeçalho do .js compilado deixa de bater), o Babel
#  standalone é carregado (cópia local em static/js/vendor/babel.min.js ou o
#  CDN) e compila o JSX ao vivo no navegador.
# -----------------------------------------------------------------------------
_pasta = os.path.join(request.folder, 'static', 'js', 'componentes')
_jsx = os.path.join(_pasta, componente + '.jsx')
_js = os.path.join(_pasta, 'compilado', componente + '.js')
# o cabeçalho do .js compilado guarda o sha256 do .jsx de origem
_hash = hashlib.sha256(open(_jsx, 'rb').read()).hexdigest() if os.path.exists(_jsx) else ''
_usar_compilado = os.path.exists(_js) and (not _hash or ('sha256:' + _hash) in open(_js, encoding='utf-8').read(600))
}}
<script src="{{=URL('static', 'js/vendor/react.production.min.js')}}"></script>
<script src="{{=URL('static', 'js/vendor/react-dom.production.min.js')}}"></script>
{{if _usar_compilado:}}
<script src="{{=URL('static', 'js/componentes/compilado/%s.js' % componente, vars=dict(v=int(os.path.getmtime(_js))))}}"></script>
{{else:}}
{{if BABEL_LOCAL:}}
<script src="{{=URL('static', 'js/vendor/babel.min.js')}}"></script>
{{else:}}
<script src="https://unpkg.com/@babel/standalone@7/babel.min.js"></script>
{{pass}}
<script type="text/babel" data-presets="react" src="{{=URL('static', 'js/componentes/%s.jsx' % componente, vars=dict(v=int(os.path.getmtime(_jsx))))}}"></script>
{{pass}}
'''

