# =============================================================================
#  PARTE 4 — INSTALADOR / LANÇADOR
#  Na primeira execução verifica e ajusta o ambiente na pasta deste arquivo:
#  Python, bibliotecas (venv/), web2py (web2py/), aplicação (applications/),
#  imagens (imagens/), rotas (routes.py) e banco de dados (loja.sqlite).
# =============================================================================
def mensagem(texto):
    linha = '[loja_didatica_2] ' + texto
    try:
        print(linha, flush=True)
    except UnicodeEncodeError:                     # console sem suporte a acentos
        codificacao = getattr(sys.stdout, 'encoding', None) or 'ascii'
        print(linha.encode(codificacao, 'replace').decode(codificacao), flush=True)


def _sha(texto):
    return hashlib.sha256(texto.encode('utf-8')).hexdigest()


# ---------------------------------------------------------------- 1. Python
def verificar_python():
    if sys.version_info < (3, 9):
        mensagem('é necessário Python 3.9 ou superior (este é o %s).' % sys.version.split()[0])
        sys.exit(1)
    mensagem('Python %s OK' % sys.version.split()[0])


# ---------------------------------------------------------------- 2. bibliotecas
DEPENDENCIAS = [('PIL', 'pillow', 'processamento das imagens enviadas pelo vendedor'),
                ('qrcode', 'qrcode', 'QR Code do PIX')]


def dependencias_faltantes():
    faltam = []
    for modulo, pacote, _ in DEPENDENCIAS:
        try:
            __import__(modulo)
        except ImportError:
            faltam.append(pacote)
    return faltam


def python_do_venv(venv_dir):
    if os.name == 'nt':
        return os.path.join(venv_dir, 'Scripts', 'python.exe')
    return os.path.join(venv_dir, 'bin', 'python')


def _pip_install(python, pacotes):
    mensagem('instalando %s (pip) ...' % ', '.join(pacotes))
    r = subprocess.call([python, '-m', 'pip', 'install', '--disable-pip-version-check', '-q'] + pacotes)
    return r == 0


def garantir_bibliotecas(offline=False):
    """Garante Pillow e qrcode. Se faltarem, cria o ambiente virtual venv/ nesta
    pasta, instala as bibliotecas nele e devolve o caminho do Python do venv
    (o programa então se reexecuta nele). Devolve None para seguir no Python atual."""
    faltam = dependencias_faltantes()
    if not faltam:
        mensagem('bibliotecas Pillow e qrcode OK')
        return None
    if offline:
        mensagem('faltam %s (modo --offline: a loja roda sem essas funções).' % ', '.join(faltam))
        return None
    venv_dir = os.path.join(RAIZ, 'venv')
    py = python_do_venv(venv_dir)
    em_algum_venv = (getattr(sys, 'base_prefix', sys.prefix) != sys.prefix or
                     hasattr(sys, 'real_prefix') or
                     os.path.abspath(sys.prefix) == os.path.abspath(venv_dir))
    if em_algum_venv:
        # já estamos em um ambiente virtual (o venv/ desta pasta ou um que você
        # mesmo ativou, como "python -m venv ." + "source bin/activate"): instala aqui
        mensagem('ambiente virtual ativo em %s: instalando %s nele ...' % (sys.prefix, ', '.join(faltam)))
        if not _pip_install(sys.executable, faltam):
            mensagem('não foi possível instalar %s; a loja roda sem essas funções.' % ', '.join(faltam))
        return None
    if not os.path.exists(py):
        mensagem('faltam %s: criando o ambiente virtual venv/ ...' % ', '.join(faltam))
        try:
            import venv
            venv.create(venv_dir, with_pip=True, clear=False)
        except Exception as e:
            mensagem('não foi possível criar o venv (%s).' % e)
            if os.name != 'nt':
                mensagem('no Debian/Ubuntu instale: sudo apt install python3-venv   '
                         '(ou: sudo apt install python3-pil python3-qrcode)')
            mensagem('tentando pip install --user ...')
            if subprocess.call([sys.executable, '-m', 'pip', 'install', '--user', '-q',
                                '--disable-pip-version-check'] + faltam) != 0:
                mensagem('não deu: a loja roda sem %s (upload de imagem / QR Code).' % ', '.join(faltam))
            return None
    if not os.path.exists(py):
        mensagem('venv criado, mas o Python %s não foi encontrado; seguindo sem %s.' % (py, ', '.join(faltam)))
        return None
    if not _pip_install(py, faltam):
        mensagem('pip falhou (sem internet?); a loja roda sem %s.' % ', '.join(faltam))
        return None
    return py


# ---------------------------------------------------------------- 3. web2py
def localizar_web2py(informado=None):
    """Procura a pasta do web2py (com web2py.py e gluon/)."""
    candidatos = [informado] if informado else []
    candidatos += [os.environ.get('WEB2PY_DIR'), os.path.join(RAIZ, 'web2py'), RAIZ,
                   os.path.join(os.path.dirname(RAIZ), 'web2py'), os.path.join(os.getcwd(), 'web2py'),
                   os.path.expanduser('~/web2py'), '/opt/web2py', 'C:/web2py']
    for c in candidatos:
        if c and os.path.isfile(os.path.join(c, 'web2py.py')) and os.path.isdir(os.path.join(c, 'gluon')):
            return os.path.abspath(c)
    return None


# pacotes que o web2py traz como submódulos do git (faltam no zip do GitHub)
SUBMODULOS = [('pydal', 'https://github.com/web2py/pydal/archive/refs/heads/master.zip'),
              ('yatl', 'https://github.com/web2py/yatl/archive/refs/heads/master.zip'),
              ('rocket3', 'https://github.com/web2py/rocket3/archive/refs/heads/master.zip')]


def _baixar(url, timeout=180):
    mensagem('baixando %s ...' % url)
    try:
        with urllib.request.urlopen(url, timeout=timeout) as resp:
            return resp.read()
    except urllib.error.URLError as e:
        # Pythons sem certificados de CA (comum no macOS do python.org): tenta sem verificar
        if 'CERTIFICATE_VERIFY_FAILED' not in str(e):
            raise
        import ssl
        mensagem('certificado SSL não verificado neste Python; baixando sem verificação ...')
        contexto = ssl._create_unverified_context()
        with urllib.request.urlopen(url, timeout=timeout, context=contexto) as resp:
            return resp.read()


def _extrair_zip_sem_raiz(dados, destino):
    """Extrai um zip do GitHub (que tem uma pasta raiz 'nome-master/') em destino/."""
    with zipfile.ZipFile(io.BytesIO(dados)) as z:
        nomes = z.namelist()
        raiz = nomes[0].split('/')[0] + '/'
        for nome in nomes:
            if not nome.startswith(raiz) or nome.endswith('/'):
                continue
            alvo = os.path.join(destino, *nome[len(raiz):].split('/'))
            os.makedirs(os.path.dirname(alvo), exist_ok=True)
            with open(alvo, 'wb') as f:
                f.write(z.read(nome))


def submodulos_ok(web2py_dir):
    return all(os.path.exists(os.path.join(web2py_dir, 'gluon', 'packages', nome, nome, '__init__.py'))
               for nome, _ in SUBMODULOS)


def completar_submodulos(web2py_dir):
    """Se pydal/yatl/rocket3 estiverem vazios (zip do GitHub ou clone sem --recursive), baixa-os."""
    for nome, url in SUBMODULOS:
        pasta = os.path.join(web2py_dir, 'gluon', 'packages', nome)
        if os.path.exists(os.path.join(pasta, nome, '__init__.py')):
            continue
        _extrair_zip_sem_raiz(_baixar(url), pasta)
    return submodulos_ok(web2py_dir)


def baixar_web2py(destino):
    """Obtém o web2py em destino: git clone --recursive; senão zips do GitHub."""
    if shutil.which('git'):
        mensagem('baixando o web2py com git (clone --recursive --depth 1) em %s ...' % destino)
        r = subprocess.call(['git', 'clone', '--recursive', '--depth', '1', WEB2PY_GIT, destino])
        if r == 0 and localizar_web2py(destino):
            if not submodulos_ok(destino):
                completar_submodulos(destino)
            return destino
        shutil.rmtree(destino, ignore_errors=True)
    try:
        _extrair_zip_sem_raiz(_baixar('https://github.com/web2py/web2py/archive/refs/heads/master.zip'), destino)
        completar_submodulos(destino)
        if localizar_web2py(destino) and submodulos_ok(destino):
            return destino
    except Exception as e:
        mensagem('download pelo GitHub falhou: %s' % e)
    try:
        dados = _baixar(WEB2PY_ZIP)
        pai = os.path.dirname(destino)
        with zipfile.ZipFile(io.BytesIO(dados)) as z:
            z.extractall(pai)                      # o zip oficial contém a pasta web2py/
        extraido = os.path.join(pai, 'web2py')
        if os.path.abspath(extraido) != os.path.abspath(destino) and os.path.isdir(extraido):
            shutil.move(extraido, destino)
        if localizar_web2py(destino):
            return destino
    except Exception as e:
        mensagem('download de %s falhou: %s' % (WEB2PY_ZIP, e))
    return None


def garantir_web2py(informado=None, offline=False):
    web2py_dir = localizar_web2py(informado)
    if web2py_dir and not submodulos_ok(web2py_dir) and not offline:
        mensagem('web2py em %s está sem pydal/yatl/rocket3; completando ...' % web2py_dir)
        completar_submodulos(web2py_dir)
    if not web2py_dir and not offline:
        web2py_dir = baixar_web2py(informado or os.path.join(RAIZ, 'web2py'))
    if web2py_dir:
        mensagem('web2py OK em %s' % web2py_dir)
    return web2py_dir


# ---------------------------------------------------------------- 4. aplicação
def extrair_aplicacao(forcar=False):
    """Grava a aplicação em <RAIZ>/applications/loja_didatica_2/.

    Primeira execução: grava tudo.  Execuções seguintes: regrava só o que mudou
    neste arquivo E que você não editou (compara com o hash do manifesto);
    arquivos editados por você são preservados, a menos que use --atualizar.
    Nunca toca em loja.sqlite, imagens/, sessions/ nem uploads/."""
    app_dir = os.path.join(RAIZ, 'applications', APP)
    for pasta in PASTAS:
        os.makedirs(os.path.join(app_dir, *pasta.split('/')), exist_ok=True)
    caminho_manifesto = os.path.join(RAIZ, MANIFESTO)
    try:
        with open(caminho_manifesto, encoding='utf-8') as f:
            manifesto = json.load(f)
    except (IOError, ValueError):
        manifesto = {}
    novos, atualizados, iguais, preservados = 0, 0, 0, []
    for rel in sorted(ARQUIVOS, key=lambda r: ('/compilado/' in r, r)):
        conteudo = ARQUIVOS[rel]
        destino = os.path.join(app_dir, *rel.split('/'))
        os.makedirs(os.path.dirname(destino), exist_ok=True)
        if os.path.exists(destino):
            with open(destino, encoding='utf-8', newline='') as f:
                atual = f.read()
            if atual == conteudo:
                iguais += 1
                manifesto[rel] = _sha(conteudo)
                continue
            editado = manifesto.get(rel) not in (None, _sha(atual))
            if editado and not forcar:
                preservados.append(rel)
                continue
            atualizados += 1
        else:
            novos += 1
        with open(destino, 'w', encoding='utf-8', newline='') as f:
            f.write(conteudo)
        manifesto[rel] = _sha(conteudo)
    with open(caminho_manifesto, 'w', encoding='utf-8') as f:
        json.dump(manifesto, f, indent=1, sort_keys=True)
    for nome, texto in [(os.path.join(RAIZ, 'applications', '__init__.py'), ''),
                        (os.path.join(app_dir, '__init__.py'), ''),
                        (os.path.join(app_dir, 'ABOUT'), 'Loja Didática 2 (v2) — aplicação web2py de exemplo.\n')]:
        if not os.path.exists(nome):
            with open(nome, 'w', encoding='utf-8') as f:
                f.write(texto)
    mensagem('aplicação OK em %s (%d novos, %d atualizados, %d iguais)' % (app_dir, novos, atualizados, iguais))
    if preservados:
        mensagem('%d arquivo(s) editado(s) por você foram preservados (use --atualizar para sobrescrever): %s'
                 % (len(preservados), ', '.join(preservados[:6]) + (' ...' if len(preservados) > 6 else '')))
    return app_dir


# ---------------------------------------------------------------- 5. imagens
def extrair_imagens(forcar=False):
    """Grava as imagens de exemplo em <RAIZ>/imagens/ (só as que faltam)."""
    pasta = os.path.join(RAIZ, 'imagens')
    os.makedirs(pasta, exist_ok=True)
    n = 0
    for nome, dados in IMAGENS.items():
        destino = os.path.join(pasta, nome)
        if os.path.exists(destino) and not forcar:
            continue
        with open(destino, 'wb') as f:
            f.write(base64.b64decode(dados))
        n += 1
    mensagem('imagens OK em %s (%d gravadas agora, %d no total)' % (pasta, n, len(IMAGENS)))
    return n


def preparar_babel(app_dir, baixar=False):
    """Babel só é preciso para editar os .jsx sem internet. Copia de <RAIZ>/vendor
    se existir; baixa do CDN com --babel."""
    destino = os.path.join(app_dir, 'static', 'js', 'vendor', 'babel.min.js')
    if os.path.exists(destino) and os.path.getsize(destino) > 1000:
        return True
    origem = os.path.join(RAIZ, 'vendor', 'babel.min.js')
    if os.path.exists(origem):
        shutil.copyfile(origem, destino)
        mensagem('Babel copiado de vendor/ (edição de .jsx sem internet habilitada).')
        return True
    if baixar:
        try:
            dados = _baixar(BABEL_URL, timeout=60)
            with open(destino, 'wb') as f:
                f.write(dados)
            return True
        except Exception as e:
            mensagem('não foi possível baixar o Babel (%s); os .jsx editados usarão o CDN.' % e)
    return False


# ---------------------------------------------------------------- 6. atalhos, rotas e banco
INICIAR_SH = """#!/usr/bin/env bash
# Inicia a Loja Didática 2 (Linux/macOS) procurando um Python 3.9+ que funcione.
# Ignora "python" quebrado (ex.: venv ativado cuja pasta foi apagada).
cd "$(dirname "$0")" || exit 1
for py in python3 python /usr/bin/python3 /usr/local/bin/python3 /opt/homebrew/bin/python3; do
  if "$py" -c "import sys; sys.exit(0 if sys.version_info >= (3, 9) else 1)" >/dev/null 2>&1; then
    exec "$py" loja_didatica_2_v2.py "$@"
  fi
done
echo "Python 3.9+ nao encontrado. Instale com: sudo apt install python3 python3-venv (Debian/Ubuntu)"
exit 1
"""

INICIAR_BAT = """@echo off
rem Inicia a Loja Didatica 2 (Windows). Usa o "py" launcher ou o python do PATH.
cd /d "%~dp0"
where py >nul 2>nul
if %errorlevel%==0 (
  py -3 loja_didatica_2_v2.py %*
  goto :fim
)
where python >nul 2>nul
if %errorlevel%==0 (
  python loja_didatica_2_v2.py %*
  goto :fim
)
echo Python 3 nao encontrado. Instale em https://www.python.org/downloads/
echo (marque "Add python.exe to PATH" no instalador) e rode este arquivo de novo.
pause
:fim
"""


def gravar_atalhos():
    """iniciar.sh (Linux/macOS) e iniciar.bat (Windows) ao lado do .py."""
    for nome, texto in (('iniciar.sh', INICIAR_SH), ('iniciar.bat', INICIAR_BAT)):
        caminho = os.path.join(RAIZ, nome)
        if os.path.exists(caminho):
            continue
        with open(caminho, 'w', encoding='utf-8', newline='\r\n' if nome.endswith('.bat') else '\n') as f:
            f.write(texto)
        if nome.endswith('.sh') and os.name != 'nt':
            try:
                os.chmod(caminho, 0o755)
            except OSError:
                pass


def gravar_routes():
    """routes.py na pasta: a loja é a aplicação padrão (responde na raiz do site)."""
    caminho = os.path.join(RAIZ, 'routes.py')
    if os.path.exists(caminho):
        return
    with open(caminho, 'w', encoding='utf-8') as f:
        f.write("# -*- coding: utf-8 -*-\n# gerado por loja_didatica_2_v2.py: a loja responde na raiz do site\n"
                "routers = dict(BASE=dict(default_application='%s'))\n" % APP)


def limpar_banco(app_dir):
    for caminho in [os.path.join(RAIZ, 'loja.sqlite'), os.path.join(RAIZ, 'loja.sqlite-journal')]:
        if os.path.exists(caminho):
            os.remove(caminho)
    sessoes = os.path.join(app_dir, 'sessions')
    shutil.rmtree(sessoes, ignore_errors=True)
    os.makedirs(sessoes, exist_ok=True)
    mensagem('loja.sqlite e sessões apagados; os dados de exemplo serão recriados.')


def verificar_banco(url_local, abrir):
    """Roda em uma thread: espera o servidor responder, faz a primeira requisição
    (que cria e povoa o loja.sqlite) e confere o banco."""
    import sqlite3
    import time
    abridor = urllib.request.build_opener(urllib.request.ProxyHandler({}))   # ignora proxy p/ localhost
    for _ in range(120):
        time.sleep(0.5)
        try:
            abridor.open(url_local, timeout=5).read()
            break
        except Exception:
            continue
    caminho = os.path.join(RAIZ, 'loja.sqlite')
    if os.path.exists(caminho):
        try:
            con = sqlite3.connect(caminho)
            tabelas = con.execute("select count(*) from sqlite_master where type='table'").fetchone()[0]
            produtos = con.execute('select count(*) from produto').fetchone()[0]
            usuarios = con.execute('select count(*) from auth_user').fetchone()[0]
            con.close()
            mensagem('banco de dados OK: %s (%d tabelas, %d produtos, %d usuários)'
                     % (caminho, tabelas, produtos, usuarios))
        except sqlite3.Error as e:
            mensagem('banco criado, mas não foi possível ler: %s' % e)
    else:
        mensagem('atenção: o banco ainda não foi criado — abra %s no navegador.' % url_local)
    mensagem('pronto! loja em ' + url_local)
    if abrir:
        webbrowser.open(url_local)


# ---------------------------------------------------------------- 7. diagnóstico e servidor
def diagnostico(web2py_informado=None):
    """Imprime o que o programa vê do ambiente (útil para pedir ajuda em aula)."""
    import platform
    print('Sistema        :', platform.platform())
    print('Python         :', sys.version.replace('\n', ' '))
    print('Executável     :', sys.executable)
    em_venv = getattr(sys, 'base_prefix', sys.prefix) != sys.prefix
    print('Ambiente virt. :', ('sim (%s)' % sys.prefix) if em_venv else 'não')
    print('Pasta projeto  :', RAIZ)
    print('Gravável       :', 'sim' if os.access(RAIZ, os.W_OK) else 'NÃO')
    faltam = dependencias_faltantes()
    print('Pillow/qrcode  :', 'OK' if not faltam else 'faltam ' + ', '.join(faltam))
    print('git            :', shutil.which('git') or 'não encontrado (o web2py será baixado em zip)')
    w = localizar_web2py(web2py_informado)
    print('web2py         :', (w + (' (completo)' if submodulos_ok(w) else ' (SEM pydal/yatl/rocket3)')) if w else 'não encontrado (será baixado em ./web2py)')
    print('loja.sqlite    :', 'existe' if os.path.exists(os.path.join(RAIZ, 'loja.sqlite')) else 'ainda não criado')
    print('imagens/       :', '%d arquivos' % len(os.listdir(os.path.join(RAIZ, 'imagens'))) if os.path.isdir(os.path.join(RAIZ, 'imagens')) else 'ainda não criada')
    print('porta 8000     :', 'livre' if porta_livre(8000) else 'ocupada')
    try:
        urllib.request.urlopen('https://github.com', timeout=6).read(200)
        print('internet       : OK (github.com acessível)')
    except Exception as e:
        print('internet       : sem acesso a github.com (%s)' % str(e)[:60])


def porta_livre(porta, ip='127.0.0.1'):
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        s.bind((ip if ip != '0.0.0.0' else '', porta))
        return True
    except OSError:
        return False
    finally:
        s.close()


def escolher_porta(porta, ip):
    p = porta
    while not porta_livre(p, ip) and p < porta + 20:
        p += 1
    if p != porta:
        mensagem('porta %d ocupada; usando %d' % (porta, p))
    return p


def iniciar_web2py(web2py_dir, ip, porta, senha, abrir):
    """Inicia o web2py neste mesmo processo, com a pasta deste arquivo como
    "applications parent" (equivale a: web2py.py -f <RAIZ>, mas sem exigir que a
    pasta contenha o gluon/). O framework é importado de web2py_dir."""
    url_local = 'http://127.0.0.1:%d/' % porta
    mensagem('iniciando o servidor em %s (Ctrl+C encerra)' % url_local)
    if ip == '0.0.0.0':
        try:
            mensagem('na rede: http://%s:%d/' % (socket.gethostbyname(socket.gethostname()), porta))
        except socket.error:
            pass
    os.environ['web2py_path'] = web2py_dir          # gluon_parent (gluon/settings.py)
    sys.path.insert(0, web2py_dir)
    os.chdir(web2py_dir)
    try:
        import gluon.widget
    except ImportError as e:
        mensagem('não foi possível importar o web2py de %s: %s' % (web2py_dir, e))
        return 1
    sys.argv = ['web2py.py', '-f', RAIZ, '-a', senha, '-i', ip, '-p', str(porta), '--no_gui']
    threading.Thread(target=verificar_banco, args=(url_local, abrir), daemon=True).start()
    gluon.widget.start()                                 # bloqueia até Ctrl+C
    return 0


def main(argv=None):
    parser = argparse.ArgumentParser(
        description='Loja Didática 2 (v2) — prepara o ambiente nesta pasta e inicia a loja.')
    parser.add_argument('--web2py', metavar='DIR', help='pasta do web2py (procurada/baixada automaticamente se omitida)')
    parser.add_argument('--porta', type=int, default=8000, help='porta do servidor (8000)')
    parser.add_argument('--rede', action='store_true', help='aceita conexões da rede (-i 0.0.0.0)')
    parser.add_argument('--ip', default=None, help='IP de escuta (127.0.0.1)')
    parser.add_argument('--senha', default='senha', help='senha do admin do web2py (senha)')
    parser.add_argument('--extrair-apenas', action='store_true', help='prepara os arquivos e sai sem iniciar o servidor')
    parser.add_argument('--atualizar', action='store_true',
                        help='sobrescreve também os arquivos da aplicação que você editou')
    parser.add_argument('--limpar-banco', action='store_true', help='apaga loja.sqlite e recria os dados demo')
    parser.add_argument('--regravar-imagens', action='store_true', help='regrava as imagens de exemplo')
    parser.add_argument('--babel', action='store_true', help='baixa o Babel standalone (editar .jsx sem internet)')
    parser.add_argument('--offline', action='store_true', help='não baixa nada nem cria o venv')
    parser.add_argument('--sem-venv', action='store_true', help='não cria venv/ (usa o Python atual mesmo sem Pillow/qrcode)')
    parser.add_argument('--sem-navegador', action='store_true', help='não abre o navegador')
    parser.add_argument('--diagnostico', action='store_true', help='mostra o que o programa vê do ambiente e sai')
    args = parser.parse_args(argv)

    mensagem('Loja Didática 2 %s — pasta do projeto: %s' % (VERSAO, RAIZ))
    if args.diagnostico:
        diagnostico(args.web2py)
        return 0
    verificar_python()
    if not args.sem_venv:
        py = garantir_bibliotecas(offline=args.offline)
        if py:
            mensagem('reexecutando com o Python do venv/ ...')
            try:
                return subprocess.call([py, os.path.abspath(__file__)] + (argv if argv is not None else sys.argv[1:]))
            except KeyboardInterrupt:
                return 0
    app_dir = extrair_aplicacao(forcar=args.atualizar)
    extrair_imagens(forcar=args.regravar_imagens)
    gravar_atalhos()
    gravar_routes()
    preparar_babel(app_dir, baixar=args.babel)
    if args.limpar_banco:
        limpar_banco(app_dir)
    web2py_dir = garantir_web2py(args.web2py, offline=args.offline)
    if not web2py_dir:
        mensagem('web2py não encontrado e não foi possível baixá-lo. Sem internet, coloque a pasta do '
                 'web2py (git clone --recursive https://github.com/web2py/web2py.git) ao lado deste '
                 'arquivo ou indique-a com --web2py DIR.')
        return 1
    if args.extrair_apenas:
        mensagem('ambiente preparado. Nada foi iniciado (--extrair-apenas).')
        return 0
    ip = args.ip or ('0.0.0.0' if args.rede else '127.0.0.1')
    porta = escolher_porta(args.porta, ip)
    return iniciar_web2py(web2py_dir, ip, porta, args.senha, not args.sem_navegador)


if __name__ == '__main__':
    codigo = main()
    if codigo and os.name == 'nt' and sys.stdin and sys.stdin.isatty():
        try:
            input('Pressione Enter para fechar...')      # deixa a mensagem visível no clique duplo
        except EOFError:
            pass
    sys.exit(codigo)
